messages.content:
Review the following files under this acceptance criterion:
Review the guide integration and routing for concrete runtime regressions, direct-link handling, Back, independent shelf state, focus/scroll restoration, bilingual persistence and isolation from existing prompt sheets. Also review safe app-home QR/PNG generation, printed iPhone opening instructions, modal focus, native sharing gesture timing, cancellation and object-URL cleanup in the included share sources. Existing unrelated app functions are context, not an invitation to invent scope. Pass absent a material demonstrated defect; fail with specific evidence if one exists.
[{"path":"src/App.tsx","content":"import "./quick-access.css";
import {
  lazy,
  Suspense,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { allPrompts as sourcePrompts } from "./prompts";
import type { Prompt, PromptVariant, ReviewSource } from "./types";
import { FirstPracticeGuide } from "./FirstPracticeGuide";
import { SavedPracticeList, RecentList } from "./QuickAccess";
import { useSavedPrompts } from "./useSavedPrompts";
import { usePromptClipboard } from "./usePromptClipboard";
import { practiceHref, shortcutKey, type PracticeShortcut, type RecentPrompt } from "./shortcuts";
import { useNavigation, navigate, replacePromptOptions } from "./navigation";
import { useAppFrame } from "./useAppFrame";
import { useRightEdgeBack } from "./useRightEdgeBack";
import { collections } from "./content/collections";
import { Icon } from "./Icon";
import { AppShare } from "./AppShare";
import { Settings } from "./Settings";
import { LearningLibrary } from "./LearningLibrary";
import { guideTitles, canonicalGuideId, readingArticleIds } from "./content/guide-titles";
import { guideEntryId } from "./guides";
import { PromptLibrary } from "./PromptLibrary";
import { composeScene, type SceneSelection } from "./scenes";
import { promptText } from "./prompt-text";
import { useAppUpdate } from "./useAppUpdate";
import { UpdateBanner } from "./UpdateBanner";
import { PromptDialog } from "./PromptDialog";
import { dictionary, initialLocale, type Locale } from "./i18n";
const GuideLibrary = lazy(() => import("./GuideLibrary").then(module => ({ default: module.GuideLibrary })));
const prompts: Prompt[] = sourcePrompts;
let storage: Storage | null = null;
try {
  storage = window.localStorage;
} catch {}
export default function App() {
  const route = useNavigation();
  const guidesVisited = useRef(false);
  if (route.page === "guides") guidesVisited.current = true;
  const appUpdate = useAppUpdate();
  const { copying, writer } = usePromptClipboard();
  const savedPrompts = useSavedPrompts(storage);
  const [sceneSelection, setSceneSelection] = useState<SceneSelection>();
  const frame = useAppFrame(route.base);
  const lastPractice = useRef("#library");
  if (route.page === "practice") lastPractice.current = route.base;
  const [locale, setLocale] = useState<Locale>(initialLocale);
  const favorites = savedPrompts.favorites;
  const [modal, setModal] = useState<{
      prompt: Prompt | null;
      content: ReactNode;
    } | null>(null),
    [variant, setVariant] = useState<PromptVariant>("full"),
    [reviewSource, setReviewSource] = useState<ReviewSource>("current"),
    [message, setMessage] = useState(""),
    [manual, setManual] = useState(false),
    [copied, setCopied] = useState(false),
    [online, setOnline] = useState(navigator.onLine),
    [installed, setInstalled] = useState(
      () =>
        matchMedia("(display-mode: standalone)").matches ||
        !!(navigator as Navigator & { standalone?: boolean }).standalone,
    );
  const install = useRef<(Event & { prompt: () => Promise<void> }) | null>(
    null,
  );
  const localHydration = useRef<string | null>(null);
  const active = useRef(modal);
  active.current = modal;
  const t = dictionary[locale],
    en = locale === "en",
    s = (zh: string, english: string) => (en ? english : zh);
  useEffect(() => {
    document.documentElement.lang = locale;
    document.title =
      locale === "en"
        ? "TalkSprout · Start speaking English"
        : "TalkSprout 开口芽 · 和 AI 开口练英语";
    try {
      localStorage.setItem("talksprout:locale", locale);
    } catch {}
  }, [locale]);
  useEffect(() => {
    const connection = () => setOnline(navigator.onLine);
    const before = (e: Event) => {
      e.preventDefault();
      install.current = e as typeof install.current;
    };
    window.addEventListener("online", connection);
    window.addEventListener("offline", connection);
    window.addEventListener("beforeinstallprompt", before);
    return () => {
      window.removeEventListener("online", connection);
      window.removeEventListener("offline", connection);
      window.removeEventListener("beforeinstallprompt", before);
    };
  }, []);
  useEffect(() => {
    if (appUpdate.cacheUnavailable)
      setMessage(en ? "Offline cache unavailable." : "离线缓存暂不可用。");
  }, [appUpdate.cacheUnavailable, en]);
  useLayoutEffect(() => {
    writer.invalidate();
    setCopied(false);
    const preserveLocalState = localHydration.current === location.hash;
    localHydration.current = null;
    if (route.promptId) {
      const prompt = prompts.find((p) => p.id === route.promptId);
      if (prompt && !preserveLocalState) {
        setSceneSelection(route.sceneSelection);
        setVariant(route.format ?? "full");
        setReviewSource(route.reviewSource ?? "current");
        setManual(false);
        setMessage("");
        setModal({ prompt, content: null });
      }
    } else if (route.infoId) {
      info(route.infoId);
    } else if (active.current) {
      setModal(null);
      setMessage("");
      setManual(false);
    }
  }, [route.promptId, route.infoId, route.base, route.sceneSelection?.sceneId, route.sceneSelection?.pace, route.format, route.reviewSource]);
  const previousBase = useRef(route.base);
  useEffect(() => {
    const previous = previousBase.current;
    previousBase.current = route.base;
    if (route.promptId || route.learningPromptId || route.infoId) return;
    const focusedAtNavigation = document.activeElement;
    const frame = requestAnimationFrame(() => {
      if (document.querySelector("dialog[open]")) return;
      // Do not override focus the user moved after navigation but before this frame.
      const focused = document.activeElement;
      if (focused !== focusedAtNavigation && focused !== document.body && focused?.isConnected) return;
      const opener = previous.startsWith("#collection/") && route.base === "#library"
        ? document.querySelector<HTMLElement>(`[data-collection="${previous.slice("#collection/".length)}"]`)
        : null;
      const guideOpener = previous.startsWith("#guides/") && (route.base === "#guides" || route.base === "#guides?section=reading")
        ? document.getElementById(guideEntryId(canonicalGuideId(previous.slice("#guides/".length))))
        : null;
      (guideOpener ?? opener ?? document.getElementById("library-heading"))?.focus({ preventScroll: true });
    });
    return () => cancelAnimationFrame(frame);
  }, [route.base]);
  useEffect(() => {
    if (!message || modal) return;
    const timer = setTimeout(() => setMessage(""), 3500);
    return () => clearTimeout(timer);
  }, [message, modal]);
  useEffect(() => {
    const complete = () => setInstalled(true);
    window.addEventListener("appinstalled", complete);
    return () => window.removeEventListener("appinstalled", complete);
  }, []);
  const openPrompt = (p: Prompt, format: PromptVariant = "full", source: ReviewSource = "current", scene?: SceneSelection, preserveManual = false) => {
    const samePurpose = (p.kind === "review") === (route.page === "review");
    const base =
      samePurpose && route.page !== "settings"
        ? route.base
        : p.kind === "review"
          ? "#review"
          : "#library";
    const params = new URLSearchParams({ prompt: p.id });
    if (format === "spoken") params.set("format", "spoken");
    if (p.kind === "review" && source === "transcript") params.set("source", "transcript");
    if (p.kind !== "review" && scene) {
      params.set("scene", scene.sceneId);
      if (scene.pace === "mock") params.set("pace", "mock");
    }
    const href = `${base}?${params}`;
    if (preserveManual && location.hash !== href) localHydration.current = href;
    navigate(href, { talksproutPrompt: p.id });
  };
  const syncOptions = (format: PromptVariant, source: ReviewSource, scene?: SceneSelection) => {
    if (modal?.prompt) replacePromptOptions(route.base, modal.prompt.id, format, source, scene,
      hash => { localHydration.current = hash; });
  };
  const resetCopyFeedback = () => {
    writer.invalidate();
    setCopied(false);
    setManual(false);
    setMessage("");
  };
  const changeLocale = (next: Locale) => {
    resetCopyFeedback();
    setLocale(next);
  };
  const closeModal = () => {
    resetCopyFeedback();
    setModal(null);
    setMessage("");
    setManual(false);
    if (route.promptId) {
      if (history.state?.talksproutPrompt === route.promptId) history.back();
      else navigate(route.base);
    } else if (route.infoId) {
      if (history.state?.talksproutInfo === route.infoId) history.back();
      else navigate(route.base);
    }
  };
  useRightEdgeBack(
    modal
      ? () => {
          if (
            history.state?.talksproutSceneBrowser &&
            history.state?.talksproutSceneCoach === route.promptId
          )
            history.back();
          else closeModal();
        }
      : route.page === "guides" && route.guideId !== undefined
        ? () => {
            if (history.state?.talksproutGuide === route.guideId) history.back();
            else navigate(readingArticleIds.has(route.guideId ?? "") ? "#guides?section=reading" : "#guides");
          }
      : route.learningPromptId
        ? () => {
            if (history.state?.talksproutLearningPrompt === route.learningPromptId)
              history.back();
            else navigate("#learning");
          }
        : route.page === "learning"
          ? () => navigate("#library")
          : route.collection
            ? () => navigate("#library")
            : null,
    `${route.base}:${route.promptId ?? route.learningPromptId ?? ""}:${route.infoId ?? ""}`,
  );
  const detail = (p: Prompt) => {
    resetCopyFeedback();
    setSceneSelection(undefined);
    setVariant("full");
    setReviewSource("current");
    setMessage("");
    setManual(false);
    setModal({ prompt: p, content: null });
    openPrompt(p);
  };
  const shortcut = (p: Prompt, format: PromptVariant, scene?: SceneSelection): PracticeShortcut => ({
    promptId: p.id, variant: format, ...(scene ? { sceneId: scene.sceneId } : {}), pace: scene?.pace ?? "coached",
  });
  const copy = async (
    p: Prompt, format: PromptVariant = "full", source: ReviewSource = "current", scene?: SceneSelection,
  ) => {
    if (copying) return;
    setCopied(false);
    setManual(false);
    setMessage("");
    let persisted = true;
    await writer.write({
      text: promptText(composeScene(p, scene), format, source, locale),
      onDelivered: async () => {
        const entry: RecentPrompt = p.kind === "review"
          ? { kind: "review", promptId: p.id, variant: format, source }
          : { kind: "practice", ...shortcut(p, format, scene) };
        persisted = await savedPrompts.record(entry);
      },
      onSuccess: () => {
        const success = p.kind === "review"
          ? s("已复制！发送到 AI 聊天，整理复习材料。", "Copied! Send in your AI chat to create review material.")
          : t.copied;
        setCopied(true);
        setMessage(persisted ? success : `${success} ${t.saveError}`);
      },
      onFailure: () => {
        setModal({ prompt: p, content: null });
        setVariant(format);
        setReviewSource(source);
        setSceneSelection(scene);
        setManual(true);
        setMessage(t.manual);
        openPrompt(p, format, source, scene, true);
      },
    });
  };
  const info = (kind: "install" | "about") => {
    resetCopyFeedback();
    setMessage("");
    setModal({
      prompt: null,
      content: (
        <>
          <h2 id="dialog-title">
            {kind === "install"
              ? s("把开口芽放进口袋", "Take TalkSprout with you")
              : s("使用说明", "About TalkSprout")}
          </h2>
          {kind === "install" ? (
            <>
              <p>
                {s(
                  "iPhone 和 iPad：在 Safari 点“分享”，选择“添加到主屏幕”。",
                  "iPhone and iPad: in Safari, choose Share → Add to Home Screen.",
                )}
              </p>
              <p>
                {s(
                  "Android：浏览器菜单选择“安装应用”或“添加到主屏幕”。桌面：点击地址栏安装图标。",
                  "Android: choose Install app or Add to Home Screen in the browser menu. Desktop: use the install icon in the address bar.",
                )}
              </p>
              <p>
                {s(
                  "首次完整加载后可离线浏览缓存内容。外部 AI 需要网络。",
                  "After a full online visit, cached content works offline. External AI requires internet access.",
                )}
              </p>
            </>
          ) : (
            <>
              <p>
                {s(
                  "选择练习 → 复制提示词 → 粘贴到外部 AI → 选择语音或文字练习。",
                  "Choose practice → copy the prompt → paste into an external AI → practice by voice or text.",
                )}
              </p>
              <p>
                {s(
                  "开始练习用于对话开头；结束与复习用于原来的对话结束后，整理笔记、句子、词汇或自测卡片。两类各有简短语音版本。",
                  "Start practice sets up a new conversation. Wrap-up & Review turns an existing chat into notes, sentences, vocabulary, or self-study cards. Both offer short spoken versions.",
                )}
              </p>
              <p>{s(
                "听读写辅助有独立收藏。常用组合保存教练、场景与练习方式；分享链接和最近复制都不包含补充背景。复习和听读写辅助的讲解语言跟随界面选择；陪练以英语练习为主，可向 AI 请求中文帮助。",
                "Learning helpers have separate favorites. Saved combinations keep the coach, scenario and format. Links and recent copies exclude extra background. Review and learning-helper explanations follow the interface language. Conversation coaches focus on English practice; ask your AI for Chinese help when needed.",
              )}</p>
              <p>
                {s(
                  "无账号、无分析追踪。收藏、最近复制和语言保存在本机，清除浏览器数据会移除记录。本站不保存 AI 聊天。",
                  "No accounts or analytics. Favorites, recent copies and language are stored locally; clearing browser data removes them. AI conversations are not stored here.",
                )}
              </p>
              <p>
                {s(
                  "等级与时长为练习建议。",
                  "Levels and durations are practice suggestions.",
                )}
              </p>
            </>
          )}
        </>
      ),
    });
    navigate(`${route.base}?info=${kind}`, { talksproutInfo: kind });
  };
  const currentCollection = collections.find((c) => c.id === route.collection);
  const currentGuideTitle = route.guideId ? guideTitles[route.guideId] : undefined;
  const title =
    route.page === "guides"
      ? currentGuideTitle?.[locale] ?? s("学习指南", "Learning guides")
      : route.page === "learning"
      ? s("听读写辅助", "Listening, reading & writing")
      : route.page === "settings"
        ? s("设置", "Settings")
        : route.page === "review"
          ? s("结束与复习", "Wrap-up & Review")
          : currentCollection
            ? en
              ? currentCollection.titleEn
              : currentCollection.category
            : s("开始练习", "Start practice");
  return (
    <div className={`app-shell${frame.keyboardOpen ? " keyboard-open" : ""}${route.page === "guides" && route.guideId !== undefined ? " guide-reading" : ""}`}>
      <a
        className="skip"
        href="#library"
        onClick={(event) => {
          event.preventDefault();
          document
            .getElementById("library-heading")
            ?.focus({ preventScroll: true });
        }}
      >
        {s("跳到内容", "Skip to content")}
      </a>
      <aside className="app-sidebar">
        <a
          className="brand"
          href="#library"
          onClick={(event) => {
            event.preventDefault();
            navigate("#library");
          }}
        >
          <img
            src={`${import.meta.env.BASE_URL}icons/icon.svg`}
            alt=""
            width="38"
            height="38"
          />
          <span>
            TalkSprout
            <small>{s("开口芽", "English, a little every day")}</small>
          </span>
        </a>
        <nav className="app-nav" aria-label={s("主导航", "Primary navigation")}>
          {(["practice", "review", "guides", "settings"] as const).map((page) => {
            const href =
              page === "practice"
                ? route.page === "practice"
                  ? "#library"
                  : lastPractice.current
                : page === "review"
                  ? "#review"
                  : page === "guides"
                    ? "#guides"
                    : "#settings";
            return (
              <a
                key={page}
                href={href}
                aria-current={
                  route.page === page ||
                  (page === "practice" && route.page === "learning")
                    ? "page"
                    : undefined
                }
                onClick={(event) => {
                  event.preventDefault();
                  if (location.hash === href)
                    frame.scrollRef.current?.scrollTo({
                      top: 0,
                      behavior: matchMedia("(prefers-reduced-motion: reduce)")
                        .matches
                        ? "auto"
                        : "smooth",
                    });
                  else navigate(href);
                }}
              >
                <Icon name={page === "guides" ? "book" : page} />
                <span>
                  {page === "practice"
                    ? s("开始练习", "Start practice")
                    : page === "review"
                      ? s("结束与复习", "Wrap-up & Review")
                      : page === "guides"
                        ? s("学习指南", "Learning guides")
                        : s("设置", "Settings")}
                </span>
              </a>
            );
          })}
        </nav>
        <p className="sidebar-note">
          {s("开口练习，回顾积累。", "Practice, review, and keep growing.")}
        </p>
      </aside>
      <main className="app-main">
        <header className="app-header">
          {((route.page === "practice" && route.collection) ||
            route.page === "learning") && (
            <button
              className="back-button icon-button"
              aria-label={
                route.page === "learning"
                  ? s("← 返回练习", "← Back to practice")
                  : s("← 返回分类", "← Back to collections")
              }
              onClick={() => navigate("#library")}
            >
              <Icon name="back" />
            </button>
          )}
          <div className="header-title">
            <span className="eyebrow">TalkSprout</span>
            <h1 id="library-heading" tabIndex={-1}>
              {title}
            </h1>
          </div>
          <span id="connection" className="connection" data-online={online}>
            {online
              ? s("随时，开口练习", "Practice anytime")
              : s("离线模式 · 练习依然在", "Offline · keep practicing")}
          </span>
          <AppShare locale={locale} writer={writer} copying={copying} onMessage={setMessage} />
          <button
            className="icon-button language-shortcut"
            aria-label={en ? "中文" : "English"}
            title={en ? "中文" : "English"}
            onClick={() => changeLocale(en ? "zh" : "en")}
          >
            <Icon name="language" />
          </button>
        </header>
        <UpdateBanner
          snapshot={appUpdate.snapshot}
          completed={appUpdate.completed}
          locale={locale}
          onUpdate={appUpdate.requestUpdate}
        />
        <div
          className="page-scroll"
          data-testid="page-scroll"
          ref={frame.scrollRef}
          onScroll={frame.onScroll}
          role="region"
          aria-label={s("页面内容", "Page content")}
          tabIndex={0}
        >
          <div
            className="workspace"
            hidden={route.page === "settings" || route.page === "learning" || route.page === "guides"}
          >
            <PromptLibrary
              locale={locale}
              purpose={route.page === "review" ? "review" : "practice"}
              collection={route.collection}
              favorites={favorites}
              copying={copying}
              onDetail={detail}
              onCopy={(p) => void copy(p)}
              homeExtras={<>
                <FirstPracticeGuide locale={locale} />
                <SavedPracticeList items={savedPrompts.shortcuts} locale={locale} onRemove={(item) => { void savedPrompts.toggleShortcut(item).then(ok => { if (!ok) setMessage(t.saveError); }); }} />
                <RecentList items={savedPrompts.recent.filter(item => item.kind === "practice")} locale={locale} />
              </>}
              reviewExtras={<RecentList items={savedPrompts.recent.filter(item => item.kind === "review")} locale={locale} />}
              onFavorite={(id) => {
                void savedPrompts.toggleFavorite(id).then(ok => { if (!ok) setMessage(t.saveError); });
              }}
            />
          </div>
          {route.page === "learning" && (
            <div className="workspace">
              <LearningLibrary
                locale={locale}
                promptId={route.learningPromptId}
                copying={copying}
                writer={writer}
                favorites={savedPrompts.learningFavorites}
                recent={savedPrompts.recent.filter(item => item.kind === "learning")}
                onFavorite={(id) => { void savedPrompts.toggleLearningFavorite(id).then(ok => { if (!ok) setMessage(t.saveError); }); }}
                onDelivered={(id) => savedPrompts.record({ kind: "learning", promptId: id })}
              />
            </div>
          )}
          {guidesVisited.current && <div className="workspace" hidden={route.page !== "guides"}>
            <Suspense fallback={<p role="status">{s("正在打开学习指南…", "Opening learning guides…")}</p>}>
              <GuideLibrary locale={locale} writer={writer} copying={copying} shelf={route.guideShelf} guideId={route.page === "guides" ? route.guideId : undefined} />
            </Suspense>
          </div>}
          {route.page === "settings" && (
            <div className="workspace">
              <Settings
                locale={locale}
                onLocale={changeLocale}
                online={online}
                installed={installed}
                offlineStatus={appUpdate.offlineStatus}
                shareAction={<AppShare locale={locale} writer={writer} copying={copying} onMessage={setMessage} placement="settings" />}
                onAbout={() => info("about")}
                onInstall={() => {
                  if (install.current) {
                    void install.current.prompt();
                    install.current = null;
                  } else info("install");
                }}
              />
            </div>
          )}
        </div>
      </main>
      {!modal && !route.learningPromptId && (
        <div
          id="toast"
          role="status"
          aria-live="polite"
          className={message ? "visible" : ""}
        >
          {message}
        </div>
      )}
      {modal && (
        <PromptDialog
          locale={locale}
          prompt={
            modal.prompt ? composeScene(modal.prompt, sceneSelection) : null
          }
          practiceActions={modal.prompt && modal.prompt.kind !== "review" ? (() => {
            const entry = shortcut(modal.prompt, variant, sceneSelection);
            const stored = savedPrompts.shortcuts.some(item => shortcutKey(item) === shortcutKey(entry));
            const url = new URL(location.href);
            url.search = "";
            url.hash = practiceHref(entry);
            return <div className="practice-actions">
              <button className="save-combination" aria-pressed={stored} onClick={() => { void savedPrompts.toggleShortcut(entry).then(ok => { if (!ok) setMessage(t.saveError); }); }}>{stored ? s("移除常用组合", "Remove practice combination") : s("保存常用组合", "Save practice combination")}</button>
              <details><summary>{s("分享练习链接", "Share practice link")}</summary>
                <label htmlFor="practice-link">{s("教练、场景与练习方式", "Coach, scenario and format")}</label>
                <input id="practice-link" readOnly value={url.href} />
                <button disabled={copying} onClick={() => {
                  setCopied(false); setManual(false); setMessage("");
                  void writer.write({ text: url.href,
                    onSuccess: () => setMessage(s("练习链接已复制。", "Practice link copied.")),
                    onFailure: () => { const field = document.getElementById("practice-link") as HTMLInputElement | null; field?.focus(); field?.select(); setMessage(s("请手动复制上方链接。", "Select and copy the link manually.")); },
                  });
                }}>{s("复制练习链接", "Copy practice link")}</button>
              </details>
              <small>{s("只保存练习选择，不包含补充背景。", "Only practice choices are saved; extra background is excluded.")}</small>
            </div>;
          })() : undefined}
          sceneSelection={sceneSelection}
          onSceneChange={(next) => {
            resetCopyFeedback();
            setSceneSelection(next);
            syncOptions(variant, reviewSource, next);
          }}
          content={modal.content}
          message={message}
          manual={manual}
          copied={copied}
          copying={copying}
          variant={variant}
          reviewSource={reviewSource}
          onSourceChange={(source) => {
            resetCopyFeedback();
            setReviewSource(source);
            syncOptions(variant, source, sceneSelection);
            setMessage("");
            setManual(false);
          }}
          onVariantChange={(format) => {
            resetCopyFeedback();
            setVariant(format);
            syncOptions(format, reviewSource, sceneSelection);
            setMessage("");
            setManual(false);
          }}
          onClose={closeModal}
          onCopy={(_p, format) => {
            if (modal.prompt)
              void copy(modal.prompt, format, reviewSource, sceneSelection);
          }}
        />
      )}
    </div>
  );
}
"},{"path":"src/navigation.ts","content":"import { useEffect, useState } from "react";
import { canonicalGuideId } from "./content/guide-titles";
import { collections } from "./content/collections";
import { allPrompts } from "./prompts";
import { learningPrompts } from "./content/learning";
import { compatibleScenes, type SceneSelection } from "./scenes";
import type { PromptVariant, ReviewSource } from "./types";

export type AppPage = "practice" | "review" | "settings" | "learning" | "guides";
export interface AppRoute {
  guideId?: string;
  guideShelf?: "reading";
  sceneSelection?: SceneSelection;
  format?: PromptVariant;
  reviewSource?: ReviewSource;
  page: AppPage;
  collection: string | null;
  base: string;
  promptId: string | null;
  learningPromptId: string | null;
  infoId: "install" | "about" | null;
}
export function readRoute(hash = location.hash): AppRoute {
  const [path, search = ""] = hash.replace(/^#/, "").split("?");
  const collection =
    collections.find((c) => path === `collection/${c.id}`)?.id ?? null;
  const page: AppPage =
    path === "guides" || path.startsWith("guides/")
      ? "guides"
      : path === "learning"
      ? "learning"
      : path === "settings"
        ? "settings"
        : path === "review" || path === "collection/review"
          ? "review"
          : "practice";
  const base =
    page === "guides"
      ? path.startsWith("guides/") ? `#guides/${canonicalGuideId(path.slice("guides/".length))}` : new URLSearchParams(search).get("section") === "reading" ? "#guides?section=reading" : "#guides"
      : page === "learning"
      ? "#learning"
      : page === "settings"
        ? "#settings"
        : page === "review"
          ? "#review"
          : collection
            ? `#collection/${collection}`
            : "#library";
  const requested = new URLSearchParams(search).get("prompt");
  const prompt = allPrompts.find((p) => p.id === requested);
  const promptId =
    prompt &&
    page !== "guides" &&
    page !== "settings" &&
    page !== "learning" &&
    (prompt.kind === "review") === (page === "review")
      ? prompt.id
      : null;
  const requestedInfo = new URLSearchParams(search).get("info");
  const infoId =
    page === "settings" &&
    (requestedInfo === "install" || requestedInfo === "about")
      ? requestedInfo
      : null;
  const learningPromptId =
    page === "learning"
      ? learningPrompts.find((p) => p.id === requested)?.id ?? null
      : null;
  const route: AppRoute = { page, collection, base, promptId, learningPromptId, infoId };
  if (base === "#guides?section=reading") route.guideShelf = "reading";
  if (page === "guides" && path.startsWith("guides/")) route.guideId = canonicalGuideId(path.slice("guides/".length));
  if (promptId && prompt) {
    const params = new URLSearchParams(search);
    const format = params.get("format");
    if (format === "full" || format === "spoken") route.format = format;
    if (page === "practice") {
      const scene = compatibleScenes(prompt).find(s => s.id === params.get("scene"));
      if (scene) route.sceneSelection = {
        sceneId: scene.id,
        pace: params.get("pace") === "mock" && prompt.id === "roleplay-coach" && scene.category === "interview" ? "mock" : "coached",
        background: "",
      };
    } else if (page === "review") {
      const source = params.get("source");
      if (source === "current" || source === "transcript") route.reviewSource = source;
    }
  }
  return route;
}
export function navigate(hash: string, state: unknown = null) {
  if (location.hash === hash) return;
  history.pushState(state, "", hash);
  window.dispatchEvent(new Event("talksprout:navigate"));
}
export function useNavigation() {
  const [route, setRoute] = useState(readRoute);
  useEffect(() => {
    const update = () => setRoute(readRoute());
    window.addEventListener("hashchange", update);
    window.addEventListener("popstate", update);
    window.addEventListener("talksprout:navigate", update);
    // Reconcile a URL changed between the first render and listener setup.
    update();
    return () => {
      window.removeEventListener("hashchange", update);
      window.removeEventListener("popstate", update);
      window.removeEventListener("talksprout:navigate", update);
    };
  }, []);
  return route;
}

/** Replace safe selections in the existing sheet entry; never serialize private background. */
export function replacePromptOptions(
  base: string, promptId: string, format: PromptVariant, source: ReviewSource,
  scene: SceneSelection | undefined, beforeReplace: (hash: string) => void,
) {
  const params = new URLSearchParams({ prompt: promptId });
  if (format === "spoken") params.set("format", "spoken");
  if (allPrompts.find(p => p.id === promptId)?.kind === "review") {
    if (source === "transcript") params.set("source", source);
  } else if (scene) {
    params.set("scene", scene.sceneId);
    if (scene.pace === "mock") params.set("pace", "mock");
  }
  const href = `${base}?${params}`;
  const replace = () => {
    const current = readRoute();
    if (current.base !== base || current.promptId !== promptId || location.hash === href) return;
    beforeReplace(href);
    history.replaceState(history.state, "", href);
    window.dispatchEvent(new Event("talksprout:navigate"));
  };
  // The picker temporarily owns a separate history entry. Replace its parent only
  // after it closes, otherwise its Back cleanup would restore the old selection.
  if (history.state?.talksproutSceneBrowser) window.addEventListener("popstate", replace, { once: true });
  else replace();
}
